import { test, expect } from "../helpers/system-control-browser";

for (const width of [1440, 1100, 768]) {
  test(`landing ring: rendered theme switches at ${width}px`, async ({
    page,
  }, info) => {
    test.skip(info.project.name !== "desktop", "Own viewport matrix");
    test.setTimeout(120_000);
    // Keep the tablet ring fully inside the viewport when the navbar is clicked.
    await page.setViewportSize({ width, height: 1400 });
    await page.emulateMedia({ reducedMotion: "no-preference" });
    await page.addInitScript(() => {
      if (!localStorage.getItem("mailloop-theme"))
        localStorage.setItem("mailloop-theme", "light");
    });
    await page.goto("/");
    const card = page.locator(".landing-batch");
    const ring = page.locator(".landing-ring");
    await expect(
      page.getByRole("button", { name: "Pause batch animation" }),
    ).toBeVisible();
    await page.evaluate(() => document.fonts.ready);

    const capture = async (name: string) => {
      await expect(page.locator("html")).not.toHaveAttribute(
        "data-theme-reveal",
      );
      // Capture the viewport without scrolling the ring and suspending the demo.
      const bounds = (await ring.boundingBox())!;
      expect(bounds.y).toBeGreaterThanOrEqual(0);
      expect(bounds.y + bounds.height).toBeLessThanOrEqual(1400);
      const png = await page.screenshot({
        clip: bounds,
        path: info.outputPath(`${name}.png`),
      });
      const styles = await ring.evaluate((element) => {
        const svg = element.querySelector("svg")!;
        return {
          strokes: [...svg.querySelectorAll("circle")].map(
            (circle) => getComputedStyle(circle).stroke,
          ),
          filter: getComputedStyle(svg).filter,
          progress:
            Number.parseFloat(
              (svg.querySelector(".landing-progress-arc") as SVGCircleElement)
                .style.strokeDasharray,
            ) /
            (2 * Math.PI * 44),
          visibility: getComputedStyle(svg).visibility,
          width: svg.getBoundingClientRect().width,
          height: svg.getBoundingClientRect().height,
        };
      });
      const pixels = await page.evaluate(
        async ({ png, strokes }) => {
          const image = new Image();
          image.src = `data:image/png;base64,${png}`;
          await image.decode();
          const canvas = document.createElement("canvas");
          canvas.width = image.width;
          canvas.height = image.height;
          const context = canvas.getContext("2d")!;
          context.drawImage(image, 0, 0);
          const data = context.getImageData(
            0,
            0,
            image.width,
            image.height,
          ).data;
          return strokes.map((stroke) => {
            const rgb = stroke
              .match(/[\d.]+/g)!
              .slice(0, 3)
              .map(Number);
            let count = 0;
            for (let i = 0; i < data.length; i += 4) {
              if (
                rgb.every(
                  (channel, index) => Math.abs(channel - data[i + index]) < 8,
                )
              )
                count++;
            }
            return count;
          });
        },
        { png: png.toString("base64"), strokes: styles.strokes },
      );
      await info.attach(`${name}-paint`, {
        body: JSON.stringify({ styles, pixels }),
        contentType: "application/json",
      });
      expect(styles.visibility).toBe("visible");
      expect(styles.strokes[1]).toBe(
        (await page.locator("html").getAttribute("data-theme")) === "light"
          ? "rgb(128, 67, 202)"
          : "rgb(177, 122, 249)",
      );
      expect(styles.width).toBeGreaterThan(90);
      expect(styles.height).toBeGreaterThan(90);
      expect(pixels[1], `${name}: purple arc pixels`).toBeGreaterThan(150);
      if (styles.progress < 0.9) {
        expect(pixels[0], `${name}: track pixels`).toBeGreaterThan(150);
      }
    };
    const switchTo = async (theme: string) => {
      await page
        .getByRole("button", { name: `Switch to ${theme} theme`, exact: true })
        .click();
      await expect(page.locator("html")).toHaveAttribute("data-theme", theme);
      await expect(page.locator("html")).not.toHaveAttribute(
        "data-theme-reveal",
      );
    };

    await capture("direct-light");
    for (const state of ["sending", "paused", "complete"] as const) {
      if (state !== "sending") {
        await page.reload();
        await expect(
          page.getByRole("button", { name: "Pause batch animation" }),
        ).toBeVisible();
      }
      if (state === "paused") {
        await page
          .getByRole("button", { name: "Pause batch animation" })
          .focus();
        await page.keyboard.press("Enter");
        await expect(card).toHaveAttribute("data-paused", "true");
      }
      if (state === "complete") {
        await expect(card).toHaveAttribute("data-done", "true", {
          timeout: 12_000,
        });
        await page
          .getByRole("button", { name: "Pause batch animation" })
          .focus();
        await page.keyboard.press("Enter");
      }
      const countdown = await page
        .locator(".landing-countdown-value")
        .textContent();
      for (const [index, theme] of [
        "dark",
        "light",
        "dark",
        "light",
      ].entries()) {
        await switchTo(theme);
        await capture(`${state}-${index}-${theme}`);
      }
      if (state !== "sending")
        await expect(page.locator(".landing-countdown-value")).toHaveText(
          countdown!,
        );
      else
        await expect(page.locator(".landing-countdown-value")).not.toHaveText(
          countdown!,
        );
    }
    // Direct dark load, reduced motion, and the non-View-Transition fallback.
    await page.evaluate(() => localStorage.setItem("mailloop-theme", "dark"));
    await page.reload();
    await expect(page.locator("html")).toHaveAttribute("data-theme", "dark");
    await capture("direct-dark");
    await page.evaluate(() =>
      Object.defineProperty(document, "startViewTransition", {
        value: undefined,
        configurable: true,
      }),
    );
    for (const theme of ["light", "dark"]) {
      await switchTo(theme);
      await capture(`fallback-${theme}`);
    }
    await page.emulateMedia({ reducedMotion: "reduce" });
    await expect(card).toHaveAttribute("data-done", "true");
    for (const theme of ["light", "dark"]) {
      await switchTo(theme);
      await capture(`reduced-${theme}`);
    }
  });
}
